sed -i 's/val modelName = activeModel?.displayName ?: "No Model"/val modelName = activeModel?.displayName ?: "No Model"\n                        val stateText = when (modelState) {\n                            is com.example.backend.models.ModelState.Active -> "using $modelName (${currentTargetLanguage})"\n                            is com.example.backend.models.ModelState.Loading -> "Loading $modelName..."\n                            is com.example.backend.models.ModelState.Failed -> "Model Failed to Load"\n                            else -> "No Model Loaded"\n                        }/g' app/src/main/java/com/example/ui/screens/ChatScreen.kt
sed -i 's/text = "using $modelName (${currentTargetLanguage})"/text = stateText/g' app/src/main/java/com/example/ui/screens/ChatScreen.kt
sed -i 's/color = TextSecondary/color = if (modelState is com.example.backend.models.ModelState.Failed) androidx.compose.ui.graphics.Color.Red else TextSecondary/g' app/src/main/java/com/example/ui/screens/ChatScreen.kt
